/* ---------- Bouquet building blocks ---------- */

function Flower({ x, y, rotate = 0, scale = 1, delay = 0, outer, inner, center }) {
  const outerAngles = [0, 45, 90, 135, 180, 225, 270, 315];
  const innerAngles = [30, 90, 150, 210, 270, 330];
  return (
    <g transform={`translate(${x},${y}) rotate(${rotate})`}>
      <g className="bloom" style={{ animationDelay: `${delay}s`, transform: `scale(${scale})` }}>
        {outerAngles.map((a) => (
          <path
            key={"o" + a}
            d="M0,0 C-11,-7 -13,-24 0,-36 C13,-24 11,-7 0,0 Z"
            fill={outer}
            transform={`rotate(${a})`}
          />
        ))}
        {innerAngles.map((a) => (
          <path
            key={"i" + a}
            d="M0,0 C-8,-5 -9,-17 0,-26 C9,-17 8,-5 0,0 Z"
            fill={inner}
            transform={`rotate(${a})`}
          />
        ))}
        <circle r="7" fill={center} />
        {[0, 60, 120, 180, 240, 300].map((a) => (
          <circle key={"s" + a} r="1.3" fill="#8a3a5c" transform={`rotate(${a}) translate(0,-4.5)`} />
        ))}
      </g>
    </g>
  );
}

function Leaf({ x, y, angle, scale = 1, color }) {
  return (
    <g transform={`translate(${x},${y}) rotate(${angle}) scale(${scale})`} opacity="0.95">
      <path d="M0,0 Q10,-17 0,-36 Q-10,-17 0,0 Z" fill={color} />
      <line x1="0" y1="-2" x2="0" y2="-33" stroke="#5f8a48" strokeWidth="1" opacity="0.4" />
    </g>
  );
}

function BabyBreath({ x, y, delay }) {
  const dots = [[0, 0], [8, -6], [-7, -8], [4, -17], [-6, -19], [10, -14]];
  return (
    <g transform={`translate(${x},${y})`}>
      <g className="bloom" style={{ animationDelay: `${delay}s` }}>
        {dots.map(([dx, dy], i) => (
          <circle key={i} cx={dx} cy={dy} r="2.6" fill="#fffaf9" opacity="0.95" />
        ))}
      </g>
    </g>
  );
}

