/* ---------- Bouquet ---------- */
function Bouquet() {
  return (
    <svg id="bouquet-svg" viewBox="0 0 300 300" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="petalPink" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0%" stopColor="#e8829f" />
          <stop offset="100%" stopColor="#ffd6e8" />
        </linearGradient>
        <linearGradient id="petalRose" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0%" stopColor="#c85a80" />
          <stop offset="100%" stopColor="#f2a3bd" />
        </linearGradient>
        <linearGradient id="petalCream" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0%" stopColor="#f0aac0" />
          <stop offset="100%" stopColor="#fff0e0" />
        </linearGradient>
        <linearGradient id="wrapGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#f2a3bd" />
          <stop offset="100%" stopColor="#d9769a" />
        </linearGradient>
      </defs>

      <g id="bouquetGroup">
        {/* wrap / cone */}
        <path d="M100,230 L200,230 L150,292 Z" fill="url(#wrapGrad)" />
        <line x1="150" y1="230" x2="150" y2="292" stroke="#fffaf9" strokeWidth="1" opacity="0.35" />
        <line x1="126" y1="230" x2="150" y2="292" stroke="#fffaf9" strokeWidth="1" opacity="0.25" />
        <line x1="174" y1="230" x2="150" y2="292" stroke="#fffaf9" strokeWidth="1" opacity="0.25" />

        {/* stems */}
        {STEM_PATHS.map((d, i) => (
          <path key={i} d={d} fill="none" stroke="#9cc17a" strokeWidth="3.2" />
        ))}

        {LEAVES.map((l, i) => (
          <Leaf key={i} {...l} />
        ))}

        {/* ribbon bow */}
        <path d="M150,224 C128,206 106,208 104,226 C106,238 130,236 150,224 Z" fill="#ffe6a8" stroke="#c85a80" strokeWidth="1.2" />
        <path d="M150,224 C172,206 194,208 196,226 C194,238 170,236 150,224 Z" fill="#ffe6a8" stroke="#c85a80" strokeWidth="1.2" />
        <path d="M150,220 L141,258 L150,251 L159,258 Z" fill="#ffe6a8" stroke="#c85a80" strokeWidth="1" />
        <circle cx="150" cy="223" r="6.5" fill="#ffd98a" stroke="#c85a80" strokeWidth="1" />

        {BABYS_BREATH.map((b, i) => (
          <BabyBreath key={i} {...b} />
        ))}
        {FLOWERS.map((f, i) => (
          <Flower key={i} {...f} />
        ))}
      </g>
    </svg>
  );
}

/* ---------- Starfield ---------- */
function Starfield() {
  const stars = useMemo(
    () =>
      Array.from({ length: 70 }).map((_, i) => ({
        id: i,
        left: Math.random() * 100,
        top: Math.random() * 100,
        size: Math.random() * 2.4 + 0.8,
        dur: 2 + Math.random() * 4,
        delay: Math.random() * 4,
      })),
    []
  );
  return (
    <div id="starfield">
      {stars.map((s) => (
        <div
          key={s.id}
          className="star"
          style={{
            width: s.size,
            height: s.size,
            left: s.left + "vw",
            top: s.top + "vh",
            animationDuration: s.dur + "s",
            animationDelay: s.delay + "s",
          }}
        />
      ))}
    </div>
  );
}

